function readStoredJson(key, fallback, isValid) {
  const stored = localStorage.getItem(key)
  if (!stored) return fallback
  try {
    const parsed = JSON.parse(stored)
    if (isValid(parsed)) return parsed
  } catch (error) {}
  localStorage.removeItem(key)
  return fallback
}
